//! Corpus `feat` records that belong to an ALREADY-COMPILED book whose
//! hand-authored per-book feat table does not hold them — the
//! `not-ingested` population of `docs/work-inventory.json`'s `feat` kind,
//! closed corpus-wide.
//!
//! **GENERATED — do not edit by hand.** Regenerate with
//! `PCGEN_CORPUS_ROOT=<pcgen>/data cargo run --locked --bin gen_feat_gap_tables`.
//! The generator applies `v06_work_inventory`'s own record predicate for
//! `Kind::Feat`, so a row here is exactly a row that inventory reported
//! `not-ingested`.
//!
//! `description` is the record's `DESC:` joined with its `BENEFIT:` when
//! both are present, and `None` when it carries neither — never a
//! fabricated placeholder. `prerequisites` is every top-level `PRE`-family
//! token verbatim, and `None` (never `Some(&[])`) when there are none.
//! `category` is the corpus `TYPE:` token's first dot-segment verbatim,
//! NOT a per-book `FeatCategory` variant name: a gap row has no per-book
//! table to take a variant from, and mapping the corpus facet onto some
//! book's enum would invent a classification the corpus never made.
//!
//! Total: 325 rows.

use super::feats_all::FeatCatalogRecord;
use super::RuleSetId;

/// The gap rows for one rule set, or an empty slice when that book has
/// none. Chained AFTER the book's hand-authored records by
/// `feats_all::all_feat_tables`, so a first-match key lookup keeps
/// resolving to the hand-authored record.
pub fn feat_gap_rows_for(rule_set: RuleSetId) -> &'static [FeatCatalogRecord] {
    match rule_set {
        RuleSetId::Crb => CORE_RULEBOOK_FEAT_GAP_ROWS,
        RuleSetId::Ce => CORE_ESSENTIALS_FEAT_GAP_ROWS,
        RuleSetId::Arg => ADVANCED_RACE_GUIDE_FEAT_GAP_ROWS,
        RuleSetId::Uc => ULTIMATE_COMBAT_FEAT_GAP_ROWS,
        RuleSetId::Ui => ULTIMATE_INTRIGUE_FEAT_GAP_ROWS,
        RuleSetId::Um => ULTIMATE_MAGIC_FEAT_GAP_ROWS,
        RuleSetId::Upsi => ULTIMATE_PSIONICS_FEAT_GAP_ROWS,
        RuleSetId::Uw => ULTIMATE_WILDERNESS_FEAT_GAP_ROWS,
        RuleSetId::Ha => HORROR_ADVENTURES_FEAT_GAP_ROWS,
        RuleSetId::Isr => INNER_SEA_RACES_FEAT_GAP_ROWS,
        RuleSetId::Oa => OCCULT_ADVENTURES_FEAT_GAP_ROWS,
        RuleSetId::Iswg => INNER_SEA_WORLD_GUIDE_FEAT_GAP_ROWS,
        RuleSetId::MonsterCodex => MONSTER_CODEX_FEAT_GAP_ROWS,
        _ => &[],
    }
}

